CREATE TABLE IF NOT EXISTS vaults (id TEXT PRIMARY KEY, inbox_pub TEXT NOT NULL, inbox_priv TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS folders (id TEXT PRIMARY KEY, vault_id TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'folder', name_ct TEXT NOT NULL, wrapped TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS folders_vault ON folders(vault_id);
CREATE TABLE IF NOT EXISTS memories (id TEXT PRIMARY KEY, vault_id TEXT NOT NULL, folder_id TEXT NOT NULL, blob TEXT NOT NULL, size INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS memories_vault ON memories(vault_id);
CREATE INDEX IF NOT EXISTS memories_folder ON memories(folder_id);
CREATE TABLE IF NOT EXISTS apps (id TEXT PRIMARY KEY, vault_id TEXT NOT NULL, name_ct TEXT NOT NULL, created INTEGER NOT NULL, last_used INTEGER);
CREATE INDEX IF NOT EXISTS apps_vault ON apps(vault_id);
CREATE TABLE IF NOT EXISTS grants (app_id TEXT NOT NULL, folder_id TEXT NOT NULL, wrapped TEXT NOT NULL, PRIMARY KEY (app_id, folder_id));
CREATE TABLE IF NOT EXISTS inbox (id TEXT PRIMARY KEY, vault_id TEXT NOT NULL, app_id TEXT NOT NULL, blob TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS inbox_vault ON inbox(vault_id);
CREATE TABLE IF NOT EXISTS reads (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, vault_id TEXT NOT NULL, app_id TEXT NOT NULL, folders TEXT NOT NULL, items INTEGER NOT NULL, ts INTEGER NOT NULL, hour INTEGER NOT NULL, leaf TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS reads_vault ON reads(vault_id);
CREATE INDEX IF NOT EXISTS reads_hour ON reads(hour);
CREATE TABLE IF NOT EXISTS seals (hour INTEGER PRIMARY KEY, root TEXT NOT NULL, reads INTEGER NOT NULL, tx TEXT, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS seal_leaves (hour INTEGER NOT NULL, idx INTEGER NOT NULL, leaf TEXT NOT NULL, PRIMARY KEY (hour, idx));
CREATE TABLE IF NOT EXISTS signals (vault_id TEXT PRIMARY KEY, handle TEXT NOT NULL UNIQUE, name TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', folders TEXT NOT NULL, bundle TEXT NOT NULL, items INTEGER NOT NULL DEFAULT 0, live INTEGER NOT NULL DEFAULT 1, holder_addr TEXT, holder INTEGER NOT NULL DEFAULT 0, holder_checked INTEGER, asks INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quotas (k TEXT PRIMARY KEY, n INTEGER NOT NULL, exp INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS demo_vaults (id TEXT PRIMARY KEY, created INTEGER NOT NULL);
